(x, y, t) => {
  const cx = 240, cy = 120;
  const sac = 1 + 14 * 0.005;
  const wx = Math.sin(x*0.02+t*0.3)*15*sac + Math.cos(y*0.015-t*0.2)*10;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10*sac;
  const sx = x+wx, sy = y+wy;
  const primes = [2,3,5,7,11,13,17,19];
  let aS=0, iS=0;
  for(let i=0; i<8; i++) {
    const p = primes[i], a = t*0.25*(i%4+1)+i*0.785;
    const r = 50+p*10+Math.sin(t*0.15*p)*25;
    const sX = cx+Math.cos(a)*r, sY = cy+Math.sin(a)*r;
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*(0.03+p*0.01)-t*(1+p*0.1));
    iS += Math.sin(d*(0.02+p*0.007)+t*(0.6+p*0.05)+1.5);
  };
  return [0, 0, 0];
}
